fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = v.len(); // exclusive

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let x = v[mid];

        if x < k {
            lo = mid + 1;
        } else if x > k {
            hi = mid;
        } else {
            return mid;
        }
    }

    // By assumption, k appears at least once in v, so the loop must return.
    unreachable!("precondition violated: target k not found in v");
}